BEGIN;
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "マネージャーが1台だけだと、落ちても既存タスクは動くが、新規のスケジューリングは止まる。", "eg": "監督が退場してもグラウンドの選手は試合を続けられるが、新しい選手交代の指示は出せない。"}'::jsonb WHERE source_ref='dca-q1' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "一度に何個ずつ・何秒間隔で入れ替えるかを --update-parallelism と --update-delay で決める。", "eg": "エスカレーターの点検で、全部止めず1段ずつ順に直しながら動かし続ける。"}'::jsonb WHERE source_ref='dca-q2' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "特定ノードに限定するなら --constraint node.labels.KEY==VALUE。", "eg": "「この資格を持つ人だけ」と配属条件を貼るようなもの。"}'::jsonb WHERE source_ref='dca-q3' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "global は全ノードに1個ずつ、replicated は指定数を好きなノードに置く。", "eg": "globalは「全店舗に1台ずつ設置」、replicatedは「合計3台を空いてる店に置く」。"}'::jsonb WHERE source_ref='dca-q4' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "サービスの起動順の依存を書くなら depends_on。", "eg": "「お湯が沸いてからカップ麺を作る」の“沸いてから”を宣言する。"}'::jsonb WHERE source_ref='dca-q5' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "稼働中サービスのレプリカ数変更は docker service scale NAME=数。", "eg": "開いている店のレジ台数を「5台にして」と後から増やす感覚。"}'::jsonb WHERE source_ref='dca-q6' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "最終イメージからビルド道具を除いて小さくするのが、マルチステージビルドの狙い。", "eg": "料理を出すとき、まな板や包丁は皿に載せない。完成品だけ渡す。"}'::jsonb WHERE source_ref='dca-q7' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "変わりにくい依存定義を先にCOPYすると、コード変更時に依存インストールのキャッシュが効く。", "eg": "毎回変わる下書きより先に、変わらない下地を塗っておけば、下地は塗り直さずに済む。"}'::jsonb WHERE source_ref='dca-q8' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "プライベートレジストリへは login→レジストリ名込みで tag→push の3手順。", "eg": "宅配で「会員登録→正しい宛名ラベル→発送」の3ステップ。"}'::jsonb WHERE source_ref='dca-q9' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "タグは貼り替わるが、ダイジェスト(sha256)は中身そのものを指すので不変。", "eg": "題名(タグ)は同じでも版が変わるが、ISBN(ダイジェスト)は中身が変われば別番号。"}'::jsonb WHERE source_ref='dca-q10' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ENTRYPOINTが固定の実行体、CMDが既定の引数。run時の引数はCMDだけ上書き。", "eg": "ペン(ENTRYPOINT)は固定で、書く紙(CMD)だけ差し替えられる。"}'::jsonb WHERE source_ref='dca-q11' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "イメージの詳細メタデータを見るなら docker image inspect。", "eg": "製品の“仕様書”を開くコマンド。"}'::jsonb WHERE source_ref='dca-q12' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "今のLinuxで推奨のストレージドライバは overlay2。", "eg": "新しい家には最新設備。古い aufs はもう選ばない。"}'::jsonb WHERE source_ref='dca-q13' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "デーモン全体の設定ファイルは /etc/docker/daemon.json。", "eg": "家全体のブレーカー設定は分電盤(/etc配下)に置くのと同じ。"}'::jsonb WHERE source_ref='dca-q14' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "自動起動オン＋今すぐ起動を1発でやるなら systemctl enable --now docker。", "eg": "「留守電をオンにしつつ、今から録音も開始」を一度に。"}'::jsonb WHERE source_ref='dca-q15' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "操作対象のDockerホストを切り替えるのが docker context。", "eg": "リモコンの「入力切替」で、操作先のテレビ(デーモン)を変える。"}'::jsonb WHERE source_ref='dca-q16' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "Docker DesktopのVM内部は直接いじれず、付属の設定に従う。", "eg": "メーカー保証付きの密閉家電。中を勝手に改造できない。"}'::jsonb WHERE source_ref='dca-q17' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "コンテナ名で名前解決したいなら、自作(user-defined)ブリッジ。", "eg": "新しく作ったチームなら、メンバーを名前で呼び合える。"}'::jsonb WHERE source_ref='dca-q18' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "特定インターフェースだけに公開するなら -p IP:ホスト:コンテナ。", "eg": "受付を正面玄関ではなく、内部の通用口だけに開ける。"}'::jsonb WHERE source_ref='dca-q19' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "複数ホストにまたがるoverlayは、Swarm有効が前提。", "eg": "複数のビルを同じフロアに見せるには、管理センターの同期が要る。"}'::jsonb WHERE source_ref='dca-q20' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "hostモードはホストのネットワークをそのまま使い、ポート公開が要らない。", "eg": "壁を取り払って、コンテナがホストの部屋に引っ越す。"}'::jsonb WHERE source_ref='dca-q21' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "サブネット・ゲートウェイ・接続コンテナのIPを見るなら docker network inspect。", "eg": "建物の設計図(サブネット)と入居者リスト(接続コンテナとIP)を一覧する。"}'::jsonb WHERE source_ref='dca-q22' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "非rootで動かすなら Dockerfile に USER appuser。", "eg": "ラインに入る前に制服(低権限ユーザー)に着替える。"}'::jsonb WHERE source_ref='dca-q23' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "権限を最小化するなら、まず --cap-drop ALL してから必要な cap だけ --cap-add。", "eg": "万能ナイフの刃を全部外し、必要な刃だけ付け直す。"}'::jsonb WHERE source_ref='dca-q24' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "署名済みイメージだけ許すなら Docker Content Trust を有効に。", "eg": "封印の判子が押されていない荷物は受け取らない。"}'::jsonb WHERE source_ref='dca-q25' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "コンテナのファイルシステムを書き込み禁止にするなら --read-only。", "eg": "展示物に「手を触れないで」のガラスケースを付ける。"}'::jsonb WHERE source_ref='dca-q26' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "呼べるシステムコールを絞るのが seccomp プロファイル。", "eg": "電話帳の危険な番号にだけ、あらかじめ発信規制をかける。"}'::jsonb WHERE source_ref='dca-q27' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ボリューム＝Docker管理領域、バインドマウント＝ホストの任意パス直結。", "eg": "専用ロッカー(ボリューム)を借りるか、自分の部屋の棚を貸す(バインド)か。"}'::jsonb WHERE source_ref='dca-q28' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "複数コンテナで共有するなら、同じボリューム名を指定。", "eg": "同じ鍵のロッカーを、2人がそれぞれ自分の棚として紐付ける。"}'::jsonb WHERE source_ref='dca-q29' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "メモリ上の高速な一時領域なら --tmpfs。", "eg": "ホワイトボード。書くのは速いが、消せば何も残らない。"}'::jsonb WHERE source_ref='dca-q30' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "未使用ボリュームを一括削除するなら docker volume prune。", "eg": "どこにも紐付いていない荷物だけを、棚卸しでまとめて捨てる。"}'::jsonb WHERE source_ref='dca-q31' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "COPYはローカルコピーのみ、ADDはURL取得やtar自動展開もできる。基本はCOPY。", "eg": "COPYは普通の運送、ADDは通販の取り寄せや開梱までする多機能版。"}'::jsonb WHERE source_ref='dca-q32' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ARGはビルド時だけ、ENVはビルド後の実行時も残る。", "eg": "ARGは工事中だけの仮設資材、ENVは完成後の備え付け設備。"}'::jsonb WHERE source_ref='dca-q33' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "exec形式(JSON配列)はシェルなし直実行で $VAR 展開が効かない。shell形式はシェル経由。", "eg": "exec＝上司に直接電話、shell＝秘書を通す(言葉を解釈してくれる)。"}'::jsonb WHERE source_ref='dca-q34' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ビルドコンテキストから不要物・機密を除くのが .dockerignore。", "eg": "引越しの荷物リストから、空箱と日記帳(機密)を外す。"}'::jsonb WHERE source_ref='dca-q35' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "commitはどう作ったか再現できないので非推奨。変更はDockerfileに書く。", "eg": "レシピなしで作った料理は、あとで同じ味を再現できない。"}'::jsonb WHERE source_ref='dca-q36' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "コンテナの生死を定期チェックし docker ps の STATUS に出すのが HEALTHCHECK。", "eg": "定期巡回の看護師が体温を計って、カルテに記録する。"}'::jsonb WHERE source_ref='dca-q37' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "saveはイメージ丸ごと(レイヤー・タグ)、exportはコンテナのファイルを履歴なしで書き出す。", "eg": "save＝本棚ごと梱包、export＝本だけ取り出して段ボールに詰める。"}'::jsonb WHERE source_ref='dca-q38' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "latestは中身が変わりうるので、本番は固定タグかダイジェストで指定する。", "eg": "「最新号」の棚は来週別の雑誌。バックナンバー指定なら必ず同じ本。"}'::jsonb WHERE source_ref='dca-q39' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "各レイヤーは読み取り専用で、実行時に一番上に書き込み層が乗る。", "eg": "OHPフィルムを重ね、一番上の白紙にだけ書き込む(下は書き換えない)。"}'::jsonb WHERE source_ref='dca-q40' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "image pruneは未使用イメージだけ、system pruneはコンテナ・ネット・キャッシュまで消す。", "eg": "服だけ処分するか、クローゼットを丸ごと大掃除するか。"}'::jsonb WHERE source_ref='dca-q41' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "複数CPU向けを一度に作ってpushするなら docker buildx build --platform ... --push。", "eg": "複数言語版の本を同時出版するには、特殊な印刷設備が要る。"}'::jsonb WHERE source_ref='dca-q42' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "シェルもライブラリも無い極小イメージなら FROM scratch。", "eg": "更地に、電気も水道もなしで自給自足できる移動式ハウスだけ置く。"}'::jsonb WHERE source_ref='dca-q43' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "rootをやめて乗っ取り時の被害を抑えるのが USER の狙い。", "eg": "作業員に工場長権限を渡さず、担当ラインだけ触れる権限に絞る。"}'::jsonb WHERE source_ref='dca-q44' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "image inspectはイメージ自体の情報だけ。実行中コンテナ一覧は出ない(それは docker ps)。", "eg": "車検証には仕様は載るが、今どこを走っているかはGPSで見る。"}'::jsonb WHERE source_ref='dca-q45' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "BuildKitは独立ステージを並列化できる。「並列できない」は誤り。", "eg": "独立した工程を同時進行できる最適化ライン。順番固定は旧式の方。"}'::jsonb WHERE source_ref='dca-q46' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "コンテナはホストのカーネル共有、VMは独自カーネルを丸ごと持つ。", "eg": "VMは各戸に基礎から建てた家、コンテナは同じ建物を仕切った共有オフィス。"}'::jsonb WHERE source_ref='dca-q47' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "隔離は名前空間、リソース制限はcgroups。この2つがコンテナの土台。", "eg": "名前空間は部屋番号を分け、cgroupsは各部屋のガス・電気の上限を決める。"}'::jsonb WHERE source_ref='dca-q48' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "メモリ上限を512MBにするなら docker run --memory 512m。", "eg": "テナントの契約アンペア(上限)を決め、超えたらブレーカーが落ちる。"}'::jsonb WHERE source_ref='dca-q49' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ログやレジストリ等、デーモン全体の永続設定を書くのが daemon.json。", "eg": "本社の社内規定書。全社員(コンテナ)に効く。"}'::jsonb WHERE source_ref='dca-q50' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ログでディスクを食い潰さないよう、1ファイルの大きさ(max-size)と本数(max-file)の上限を決める。", "eg": "日記ノートの最大ページ数と冊数を決め、古いものは自動廃棄。"}'::jsonb WHERE source_ref='dca-q51' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "接続先デーモン(ローカル/リモート/Swarm)を切り替えるのが docker context。", "eg": "リモコンのチャンネルを変えて、操作するテレビ(サーバ)を切り替える。"}'::jsonb WHERE source_ref='dca-q52' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "何がディスクをどれだけ使っているかを見るなら docker system df。", "eg": "家の荷物量を、部屋ごとに集計したリスト。"}'::jsonb WHERE source_ref='dca-q53' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "CPUを1.5コアに制限するなら docker run --cpus 1.5。", "eg": "「最大1.5台分のロボットまで」と作業量の上限を設ける。"}'::jsonb WHERE source_ref='dca-q54' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "デフォルトのdocker0は名前解決できず、コンテナ間はIP直指定。だから自作ブリッジ推奨。", "eg": "古い社宅は部屋番号で呼ぶしかない。新ビルは内線名(コンテナ名)で呼べる。"}'::jsonb WHERE source_ref='dca-q55' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "hostモードはホストのネット名前空間を共有し、ポート公開なしで直に使う。", "eg": "賃貸(独自IP)でなく、実家(ホストと同じ住所)に住む。"}'::jsonb WHERE source_ref='dca-q56' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ネットを一切持たない完全隔離なら --network none。", "eg": "ネット未接続の、完全オフラインPC(エアギャップ)。"}'::jsonb WHERE source_ref='dca-q57' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "自作ブリッジで名前で繋がるのは、Docker内蔵DNSが名前とIPを自動解決するから。", "eg": "社内の内線電話帳が「名前→内線番号」を自動で登録してくれる。"}'::jsonb WHERE source_ref='dca-q58' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "小文字-pはポート明示指定、大文字-PはEXPOSE済みを空きホストポートへ自動割当。", "eg": "-pは会議室を番号指定で予約、-Pは空き部屋をお任せで割り当ててもらう。"}'::jsonb WHERE source_ref='dca-q59' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "複数ホストにまたがる通信ならoverlay(Swarmで使う)。", "eg": "離れた工場の機械を、仮想の社内LANでつなぐ。"}'::jsonb WHERE source_ref='dca-q60' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "コンテナに物理NIC直結のMAC/IPを与え、物理ネットに1台の機器として繋ぐならmacvlan。", "eg": "コンテナに、本物のLAN端子を直接挿したようなもの。"}'::jsonb WHERE source_ref='dca-q61' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "どのノードに来た要求もサービスの実体へ振り分けるのが、Swarmのingress。", "eg": "どの受付に行っても、目的の部屋へ案内してくれる。"}'::jsonb WHERE source_ref='dca-q62' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "コンテナの外向き通信は、送信元IPをホストIPに書き換える(SNAT/MASQUERADE)。", "eg": "ビル内の電話は代表番号で外にかける。中の内線は外から見えない。"}'::jsonb WHERE source_ref='dca-q63' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "名前空間は「見える範囲」の分離で、ディスクI/O帯域の制限はしない(それはcgroups)。", "eg": "名前空間は目隠し(見え方)、cgroupsはメーター(使える量)。I/O帯域はメーター側。"}'::jsonb WHERE source_ref='dca-q64' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "権限を個別に足し引きするなら --cap-add / --cap-drop。", "eg": "役職の初期権限に、必要な権限を足し、危険な権限を外す人事設定。"}'::jsonb WHERE source_ref='dca-q65' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ルートファイルシステムを書き込み禁止にするなら --read-only。", "eg": "展示品をガラスケースへ。書ける所(/tmp)は別で用意する。"}'::jsonb WHERE source_ref='dca-q66' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "マネージャーが機密を暗号化保管し、必要なコンテナの /run/secrets/ にだけ渡すのが secret。", "eg": "金庫が暗証番号を保管し、担当者にだけ口頭で手渡す(紙に残さない)。"}'::jsonb WHERE source_ref='dca-q67' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "呼べるシステムコールを絞り、カーネルへの攻撃面を減らすのが seccomp。", "eg": "OSへの命令を検閲し、危険な命令だけ弾く。"}'::jsonb WHERE source_ref='dca-q68' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "--privilegedはホストのデバイス・カーネルにほぼ何でもでき、脱走(エスケープ)の危険が大きい。", "eg": "一般社員に、全社の管理者パスワードを渡すようなもの。"}'::jsonb WHERE source_ref='dca-q69' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "DOCKER_CONTENT_TRUST=1 で、未署名イメージのpull/pushを拒否する。", "eg": "差出人の実印がない郵便は受け取らない、宅配ボックス。"}'::jsonb WHERE source_ref='dca-q70' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ボリューム＝Docker管理、バインド＝ホスト直結、tmpfs＝メモリ上の一時。", "eg": "倉庫(ボリューム)、自分の机の引き出し(バインド)、メモ帳(tmpfs)。"}'::jsonb WHERE source_ref='dca-q71' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "名前付きは一覧で見え再利用可、匿名は名前なしで rm -v で一緒に消せる。", "eg": "名刺のある荷物(名前付き)か、番号シールだけの荷物(匿名)か。"}'::jsonb WHERE source_ref='dca-q72' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "ボリュームの実体パスやドライバー等を見るなら docker volume inspect。", "eg": "登記簿で土地の所在地は分かるが、住人(使用コンテナ)は住民票で見る。"}'::jsonb WHERE source_ref='dca-q73' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "読み取り専用の層を重ね、上に書き込み層を置き、書く時だけコピー(CoW)する。", "eg": "重ねたOHPの、一番上の白紙にだけ書く。下は書き換えない。"}'::jsonb WHERE source_ref='dca-q74' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "一時コンテナでマウントし tar で書き出すのが、ボリュームバックアップの定番。", "eg": "倉庫の荷物は、一時作業員を雇って梱包して外に出す(専用エレベーターは無い)。"}'::jsonb WHERE source_ref='dca-q75' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "速いが停止で消える一時領域なら --tmpfs /tmp。", "eg": "ホワイトボード。会議中は使えるが、終われば消える。"}'::jsonb WHERE source_ref='dca-q76' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "Dockerはファイルロックを提供しないので、同一ボリュームへの同時書き込みは競合しうる。", "eg": "同じ書類を複数人が同時に編集すると、上書きや消失が起きる。"}'::jsonb WHERE source_ref='dca-q77' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "configは非機密の設定ファイル、secretは機密値を暗号化して配る。", "eg": "config＝社内規定書、secret＝金庫の暗証番号。"}'::jsonb WHERE source_ref='dca-q78' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "unhealthyになったタスクは止め、新タスクを立て直す(自動復旧)。", "eg": "具合の悪い子は休ませ、新しい元気な子を呼ぶ保護者。"}'::jsonb WHERE source_ref='dca-q79' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "drainはそのノードのタスクを退避させ、新規も置かなくする。", "eg": "メンテ前に、作業中の製品を別ラインに移してからラインを止める。"}'::jsonb WHERE source_ref='dca-q80' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"point": "constraintは必須条件(満たさねば置かない)、placement-prefはできれば従う優先度。", "eg": "constraintは採用条件(不適合は不採用)、placement-prefは配属希望(満杯なら別へ)。"}'::jsonb WHERE source_ref='dca-q81' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
UPDATE public.questions SET explanation_data = explanation_data || '{"kid": "COPYはローカルのファイルをコピーするだけ。ADDはURL取得やtar自動展開もできる（できる分、挙動が読みにくい）。"}'::jsonb WHERE source_ref='dca-q32' AND subject_id=(SELECT id FROM public.subjects WHERE slug='dca');
COMMIT;
